draw(G--I,linewidth(0.7));
draw(C--H,linewidth(0.7));
label("2",(19,12),N);
draw((20,-2)--(36,-2));
draw((18,-4)--(36,-4));
draw((20,-2.5)--(20,-1.5));
draw((36,-2.5)--(36,-1.5));
draw((18,-3.5)--(18,-4.5));
draw((36,-3.5)--(36,-4.5));
label("{\tiny 16}",(28,-2),S);
label("{\tiny 18}",(27,-4),S);
label("12",(20,6),E);
label("$E$",I,S);
label("{\tiny $H$}",H,SE);
label("$B$",B,SE);
label("$F$",F,NE);
label("$C$",C,NE);
label("$G$",G,SW);
